node <<'NODE'
const fs = require('fs');
const path = require('path');
const input = JSON.parse(process.env.N8N_STATE_INPUT || '{}');
const filePath = input.statePath;
const directory = path.dirname(filePath);
fs.mkdirSync(directory, { recursive: true });
let state = { version: 1, entities: { project: [], milestone: [], task: [] } };
if (fs.existsSync(filePath)) {
  try {
    state = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (error) {
    state = { version: 1, entities: { project: [], milestone: [], task: [] } };
  }
}
const entityType = input.record.entityType;
const bucket = state.entities[entityType] || [];
const next = bucket.filter((entry) => !(entry.notionId && entry.notionId === input.record.notionId) && !(entry.linearId && entry.linearId === input.record.linearId));
next.push(input.record);
state.entities[entityType] = next;
fs.writeFileSync(filePath, JSON.stringify(state, null, 2));
process.stdout.write(JSON.stringify({ ok: true, entityType, saved: input.record }));
NODE

